import json,sys,subprocess
L="الدرس ٢ · الدولة المصرية القديمة ومقاومة الاحتلال"
V={
'01':dict(b='L2A',cut='L2A.12',st=[('L2A.1','إنت هنا والمفتاح'),('L2A.3','سلاح ذو حدين'),('L2A.5','أولًا: دوافع احتلال مصر'),('L2A.8','التنافس الدولي والأمن القومي'),('L2A.10','الدوافع الستة')],
 pz=[('L2A.5','الفكرة الرئيسة · الكتاب ص٢١–٢٢',["الموقع الجغرافي المتميز لمصر ومواردها الاقتصادية الضخمة جعلاها مهمة في العالم القديم","لكن فترات ضعف الدولة جعلتها هدفًا للأطماع الخارجية","سؤال الدرس: «كيف كان الموقع الجغرافي لمصر سلاحًا ذا حدين؟»"]),
     ('L2A.10','مفاهيم الدرس · الكتاب ص٢٢',["الاحتلال: «سيطرة دولة قوية على أراضي دولة وفرض نفوذها السياسي والإداري عليها من دون موافقة شعبها؛ مما يؤدي إلى تقييد سيادة الدولة المحتلة»","التنافس الدولي: «صراع بين القوى الكبرى للسيطرة على مناطق النفوذ والمصالح»","الأمن القومي: «قدرة الدولة على حماية أراضيها وسيادتها وشعبها ومواردها ومصالحها من التهديدات الداخلية والخارجية»"]),
     ('END','دوافع احتلال مصر · الكتاب ص٢٢',["الموقع على مفترق طرق ثلاث قارات · الإشراف على طُرق التجارة العالمية","خصوبة الأرض ووفرة المحاصيل · مخزن الحبوب للدول الكبرى (مثل روما)","التوسع والتنافس الدولي · الرغبة في السيطرة على موازين القوى بالمنطقة","القوى: الهكسوس والفرس واليونان والرومان؛ «الأمر الذي هدد أمنها القومي بشكل مباشر»"])]),
'03':dict(b='L2B',st=[('L2B1','الفرس: قمبيز والمقاومة'),('L2B2','الإسكندر الأكبر'),('L2B3','البطالمة'),('RB','دقيقة المراجعة')],
 pz=[('L2B2','الغزو الفارسي · الكتاب ص٢٥',["العصر المتأخر: «اضطراب سياسي وصراع داخلي» جعل مصر هدفًا للأطماع الخارجية","عام 525 ق.م دخل الفُرس مصر بقيادة الملك قمبيز الثاني، وأسسوا الأسرة السابعة والعشرين","«لم يتقبل الشعب المصري الاحتلال الفارسي، وظهرت حركات المقاومة والثورات لاستعادة الاستقلال الوطني»","وده «عكس تمسّك المصريين بهُويتهم ورفضهم للسيطرة الأجنبية»"]),
     ('L2B3','الإسكندر الأكبر · الكتاب ص٢٦',["وصل مصر عام 332 ق.م، والبلاد تعاني «وطأة الحكم الفارسي والضرائب المثقلة»","دخلها «من دون مقاومة تُذكَر»؛ لأن المصريين وجدوا فيه فرصة للتخلص من الحكم الفارسي","ثبّت حكمه: اعتراف ديني بسلطته «ابن الإله آمون»، واحترام عادات المصريين وتقاليدهم","أسّس الإسكندرية «لتصبح مركزًا تجاريًا وثقافيًا وعسكريًا»"]),
     ('RB','البطالمة · الكتاب ص٢٧',["بعد وفاة الإسكندر عام 323 ق.م دخل قادة جيشه في صراع على أراضي الإمبراطورية","برز القائد بطلميوس بن لاجوس، و«فرض سيطرته على مصر وجعلها قاعدة لحكمه»","وبدأت مرحلة جديدة في تاريخ مصر: عصر البطالمة"])]),
'04':dict(b='L2C',st=[('L2C1','الرومان: ليه مصر؟'),('L2C2','الإدارة الرومانية'),('L2C3','المقاومة المصرية للحكم الروماني'),('L2C4','درس الدرس')],
 pz=[('L2C2','الرومان · الكتاب ص٢٧',["البطالمة: «اضطرابات داخلية وصراعات على السُلطة أضعفت قدرتها على حماية استقلالها»","مصر للرومان مركز اقتصادي وإستراتيجي: من أهم مصادر الحبوب، وموقعها يتحكم في طُرق التجارة بين الشرق والغرب","بعد هزيمة كليوبترا السابعة في معركة أكتيوم البحرية سيطر أكتافيوس على مصر، فبقت من أهم الولايات الرومانية"]),
     ('L2C3','الإدارة الرومانية · الكتاب ص٢٧',["مصر يديرها حاكم روماني تابع للإمبراطور مباشرةً، ويخضع له وحده","«ولا يجوز لأي عضو من مجلس الشيوخ الروماني دخولها إلا بإذن خاص من الإمبراطور»","السبب: «لما لمصر من أهمية إستراتيجية واقتصادية كبرى للإمبراطورية»"]),
     ('L2C4','المقاومة المصرية · الكتاب ص٢٧–٢٨',["زاد اضطهاد الرومان بعد اعتناق المصريين المسيحية، وبلغ ذروته في عهد دقلديانوس: «عصر الشهداء»","انتهى بعد اعتراف الإمبراطور قسطنطين بالمسيحية وإعلانه سياسة التسامح الديني","ثورات بسبب الضرائب، والمصريون «ظلوا متمسكين بهُويتهم الوطنية ورافضين للسيطرة الأجنبية»"]),
     ('END','الفكرة الرئيسة للدرس · الكتاب ص٢١',["الموقع الجغرافي المتميز والموارد الاقتصادية الضخمة جعلا مصر مهمة في العالم القديم","لكن فترات ضعف الدولة جعلتها هدفًا للأطماع الخارجية","العامل المشترك في الهكسوس والفرس والرومان: ضعف من الداخل استغلته قوة من الخارج"])]),
}
for k in sys.argv[1:]:
    v=V[k];b=v['b'];d=json.load(open(f'/home/claude/voice/src_{b}.json'));tl=json.load(open(f'/home/claude/render/{b}_tl.json'))
    W={s['key']:s['w'] for s in tl['segs'] if 'key' in s};SL=d['SL']
    def start(code):
        if code=='END': return None
        i=[s['name'].split(' ')[0] for s in SL].index(code);t0=SL[i]['t'];t1=SL[i+1]['t'] if i+1<len(SL) else 1e9
        return min(W[f"{l['id']}#{l['ix']}"] for l in d['L'] if t0<=l['t']<t1 and f"{l['id']}#{l['ix']}" in W)
    src=f'/home/claude/out/khutwa_hist_{b}_voice.mp4'
    if v.get('cut'):
        c=start(v['cut'])-0.15;s2=f'/home/claude/montage/src_d2_{k}.mp4'
        subprocess.run(['ffmpeg','-v','error','-y','-i',src,'-t',f'{c:.3f}','-c:v','libx264','-preset','veryfast','-crf','20','-c:a','aac','-b:a','160k',s2],check=True);src=s2
    dur=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',src]))
    secs=[{'at':0 if i==0 else start(c),'title':t} for i,(c,t) in enumerate(v['st'])]
    pz=[]
    for c,h,pts in v['pz']:
        a=start(c);a=dur-0.05 if a is None else a
        back=max([s['at'] for s in secs if s['at']<a-1] or [0])
        pz.append({'at':a,'back':back,'head':h,'points':pts,'dur':15})
    cfg={'src':src,'out':f'/home/claude/montage/d2_{k}_final.mp4','lesson':L,'part':f'{int(k)}/6','sections':secs,'pauses':pz}
    json.dump(cfg,open(f'/home/claude/montage/cfg/d2_{k}.json','w'),ensure_ascii=False,indent=1);print(k,[round(s['at']) for s in secs],[round(p['at']) for p in pz],round(dur))
